import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.Mac;
import java.security.SecureRandom;
import java.util.Base64;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Arrays;

public class SecureAuthVault {

    private final ConcurrentHashMap<String, EncryptedCredential> vault = new ConcurrentHashMap<>();
    private final AtomicReference<byte[]> masterKey = new AtomicReference<>();
    private final AtomicLong sequenceCounter = new AtomicLong(0);
    private final Object sealLock = new Object();
    private volatile boolean sealed = true;

    public static class EncryptedCredential {
        final byte[] ciphertext;
        final byte[] iv;
        final long sequence;
        final byte[] integrityTag;

        EncryptedCredential(byte[] ciphertext, byte[] iv, long sequence, byte[] integrityTag) {
            this.ciphertext = ciphertext;
            this.iv = iv;
            this.sequence = sequence;
            this.integrityTag = integrityTag;
        }
    }

    public void unseal(byte[] keyMaterial) throws Exception {
        if (keyMaterial == null || keyMaterial.length < 32) {
            throw new IllegalArgumentException("Key material must be at least 32 bytes");
        }
        synchronized (sealLock) {
            byte[] derived = deriveKey(keyMaterial);
            masterKey.set(derived);
            sealed = false;
        }
    }

    public void seal() {
        synchronized (sealLock) {
            byte[] key = masterKey.get();
            if (key != null) {
                Arrays.fill(key, (byte) 0);
            }
            masterKey.set(null);
            sealed = true;
        }
    }

    public void storeCredential(String userId, String credential) throws Exception {
        requireUnsealed();
        byte[] key = masterKey.get();
        if (key == null) throw new IllegalStateException("Vault sealed during operation");

        long seq = sequenceCounter.incrementAndGet();
        byte[] iv = generateIv();
        byte[] plaintext = credential.getBytes(StandardCharsets.UTF_8);
        byte[] ciphertext = encrypt(plaintext, key, iv);
        byte[] tag = computeIntegrityTag(userId, ciphertext, iv, seq, key);

        vault.put(userId, new EncryptedCredential(ciphertext, iv, seq, tag));
        Arrays.fill(plaintext, (byte) 0);
    }

    public String retrieveCredential(String userId, AuthToken token) throws Exception {
        requireUnsealed();
        validateToken(token, userId);

        EncryptedCredential cred = vault.get(userId);
        if (cred == null) throw new IllegalArgumentException("No credential for user");

        byte[] key = masterKey.get();
        if (key == null) throw new IllegalStateException("Vault sealed during operation");

        byte[] expectedTag = computeIntegrityTag(userId, cred.ciphertext, cred.iv, cred.sequence, key);
        if (!constantTimeEquals(expectedTag, cred.integrityTag)) {
            throw new SecurityException("Integrity check failed");
        }

        byte[] plaintext = decrypt(cred.ciphertext, key, cred.iv);
        return new String(plaintext, StandardCharsets.UTF_8);
    }

    public AuthToken issueToken(String userId, byte[] authProof) throws Exception {
        requireUnsealed();
        byte[] key = masterKey.get();
        if (key == null) throw new IllegalStateException("Vault sealed");

        long timestamp = System.currentTimeMillis();
        long seq = sequenceCounter.get();
        byte[] tokenData = (userId + ":" + timestamp + ":" + seq).getBytes(StandardCharsets.UTF_8);
        byte[] signature = hmacSign(tokenData, key);

        return new AuthToken(userId, timestamp, seq, signature);
    }

    private void validateToken(AuthToken token, String userId) throws Exception {
        if (!token.userId.equals(userId)) {
            throw new SecurityException("Token user mismatch");
        }
        long now = System.currentTimeMillis();
        if (now - token.timestamp > 300000) {
            throw new SecurityException("Token expired");
        }
        // Validate sequence: token must have been issued at or after current vault sequence
        // This prevents replay with tokens from before a re-key
        long currentSeq = sequenceCounter.get();
        if (token.sequence > currentSeq) {
            throw new SecurityException("Token from future sequence");
        }

        byte[] key = masterKey.get();
        if (key == null) throw new IllegalStateException("Vault sealed");
        byte[] tokenData = (userId + ":" + token.timestamp + ":" + token.sequence).getBytes(StandardCharsets.UTF_8);
        byte[] expectedSig = hmacSign(tokenData, key);
        if (!constantTimeEquals(expectedSig, token.signature)) {
            throw new SecurityException("Invalid token signature");
        }
    }

    private byte[] deriveKey(byte[] material) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        md.update("vault-key-derivation-v1".getBytes(StandardCharsets.UTF_8));
        md.update(material);
        return md.digest();
    }

    private byte[] encrypt(byte[] plaintext, byte[] key, byte[] iv) throws Exception {
        SecretKeySpec keySpec = new SecretKeySpec(key, "AES");
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, new IvParameterSpec(iv));
        return cipher.doFinal(plaintext);
    }

    private byte[] decrypt(byte[] ciphertext, byte[] key, byte[] iv) throws Exception {
        SecretKeySpec keySpec = new SecretKeySpec(key, "AES");
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.DECRYPT_MODE, keySpec, new IvParameterSpec(iv));
        return cipher.doFinal(ciphertext);
    }

    private byte[] generateIv() {
        byte[] iv = new byte[16];
        new SecureRandom().nextBytes(iv);
        return iv;
    }

    private byte[] computeIntegrityTag(String userId, byte[] ciphertext, byte[] iv, long seq, byte[] key) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        SecretKeySpec keySpec = new SecretKeySpec(key, "HmacSHA256");
        mac.init(keySpec);
        mac.update(userId.getBytes(StandardCharsets.UTF_8));
        mac.update(ciphertext);
        mac.update(iv);
        mac.update(longToBytes(seq));
        return mac.doFinal();
    }

    private byte[] hmacSign(byte[] data, byte[] key) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        SecretKeySpec keySpec = new SecretKeySpec(key, "HmacSHA256");
        mac.init(keySpec);
        return mac.doFinal(data);
    }

    private boolean constantTimeEquals(byte[] a, byte[] b) {
        if (a.length != b.length) return false;
        int result = 0;
        for (int i = 0; i < a.length; i++) {
            result |= a[i] ^ b[i];
        }
        return result == 0;
    }

    private void requireUnsealed() {
        if (sealed) throw new IllegalStateException("Vault is sealed");
    }

    private byte[] longToBytes(long val) {
        byte[] result = new byte[8];
        for (int i = 7; i >= 0; i--) {
            result[i] = (byte) (val & 0xFF);
            val >>= 8;
        }
        return result;
    }

    public static class AuthToken {
        final String userId;
        final long timestamp;
        final long sequence;
        final byte[] signature;

        AuthToken(String userId, long timestamp, long sequence, byte[] signature) {
            this.userId = userId;
            this.timestamp = timestamp;
            this.sequence = sequence;
            this.signature = signature;
        }
    }
}
